import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.D6hBiDio.js";const u=JSON.parse('{"title":"Self-Build Firmware","description":"Embed the latest tailscale from this repository in self-built OpenWrt firmware — build_feed.sh usage and alternatives","frontmatter":{"title":"Self-Build Firmware","description":"Embed the latest tailscale from this repository in self-built OpenWrt firmware — build_feed.sh usage and alternatives"},"headers":[],"relativePath":"en/build/self-build.md","filePath":"en/build/self-build.md","lastUpdated":1788749082000}'),o={name:"en/build/self-build.md"};function s(r,e,n,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="self-build-firmware-buildroot" tabindex="-1">Self-Build Firmware (Buildroot) <a class="header-anchor" href="#self-build-firmware-buildroot" aria-label="Permalink to &quot;Self-Build Firmware (Buildroot)&quot;">​</a></h1><p>Guide to embedding this repository&#39;s tailscale into a self-built OpenWrt firmware.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><ul><li>You compile your own OpenWrt firmware and want the latest tailscale built in</li><li>The official packages feed stopped updating tailscale (e.g. frozen 24.10 branches still ship an old version)</li></ul><h2 id="option-1-install-the-prebuilt-ipk-directly-no-compilation" tabindex="-1">Option 1: Install the Prebuilt IPK Directly (No Compilation) <a class="header-anchor" href="#option-1-install-the-prebuilt-ipk-directly-no-compilation" aria-label="Permalink to &quot;Option 1: Install the Prebuilt IPK Directly (No Compilation)&quot;">​</a></h2><p>If you just want the latest version on an existing firmware, install the prebuilt ipk from this repository — the steps are identical to a standard install, see <a href="/openwrt-tailscale/en/guide/manual-install.html">Manual Install</a>. No buildroot needed.</p><blockquote><p>Note: after a firmware upgrade, preinstalled packages are restored to the firmware&#39;s built-in version and need to be reinstalled.</p></blockquote><h2 id="option-2-one-click-script-build-feed-sh" tabindex="-1">Option 2: One-Click Script (build_feed.sh) <a class="header-anchor" href="#option-2-one-click-script-build-feed-sh" aria-label="Permalink to &quot;Option 2: One-Click Script (build_feed.sh)&quot;">​</a></h2><p>Automates the whole process inside your buildroot: replaces the Go toolchain, registers this repository as a feed, removes the stale official package, and selects + builds tailscale.</p><h3 id="one-line-run-no-local-checkout" tabindex="-1">One-Line Run (No Local Checkout) <a class="header-anchor" href="#one-line-run-no-local-checkout" aria-label="Permalink to &quot;One-Line Run (No Local Checkout)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/GuNanOvO/openwrt-tailscale/main/build_scripts/build_feed.sh)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt/buildroot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="local-mode-development" tabindex="-1">Local Mode (Development) <a class="header-anchor" href="#local-mode-development" aria-label="Permalink to &quot;Local Mode (Development)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build_scripts/build_feed.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt/buildroot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt-tailscale</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The second argument points to a local checkout of this repository, mounted via <code>src-link</code>.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--no-compile</code></td><td>Set up the feed and select the package only, no compilation (implies <code>--no-index</code>)</td></tr><tr><td><code>--no-index</code></td><td>Skip <code>make package/index</code></td></tr><tr><td><code>--go-version &lt;ver&gt;</code></td><td>Pin the Go toolchain version (default: auto-detect latest stable)</td></tr><tr><td><code>-h</code> / <code>--help</code></td><td>Show full help</td></tr></tbody></table><p>Environment variables: <code>JOBS</code> (parallel jobs), <code>REPO_URL</code> (mirror URL), <code>GO_VERSION</code> (pinned Go version).</p><h3 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h3><ol><li>Resolve the Go version (auto-detected unless pinned; offline fallback 1.26.6)</li><li>Override the buildroot&#39;s Go with <code>prepare_go_for_openwrt.sh</code></li><li>Register the <code>openwrt_tailscale</code> feed</li><li>Remove the official tailscale links from other feeds</li><li>Install this repository&#39;s package and enable <code>CONFIG_PACKAGE_tailscale=y</code></li><li>Compile and verify the output</li></ol><p>The script is idempotent: after <code>./scripts/feeds update -a</code> brings the official package back, re-run the script to restore the override.</p><h2 id="manual-steps-alternative" tabindex="-1">Manual Steps (Alternative) <a class="header-anchor" href="#manual-steps-alternative" aria-label="Permalink to &quot;Manual Steps (Alternative)&quot;">​</a></h2><p>For a fully manual approach, see <code>package/tailscale/FORK.md</code> in the repository.</p><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><p><code>build_feed.sh</code> is a community contribution (maintained by <a href="https://github.com/Potterli20" target="_blank" rel="noreferrer">@Potterli20</a>, originating from <a href="https://github.com/GuNanOvO/openwrt-tailscale/issues/142" target="_blank" rel="noreferrer">issue #142</a>) and is not part of this repository&#39;s core distribution workflow. Please submit script issues via <a href="https://github.com/GuNanOvO/openwrt-tailscale/pulls" target="_blank" rel="noreferrer">GitHub PR</a>.</p>',24)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
